#!/usr/bin/env python3
"""Offline SIP identity boundary processor (PROTOCOL.md, revision 1).

Reads one JSON batch object on stdin, writes one JSON results object on
stdout.  All parsing, normalization and boundary policy is implemented here
using only the Python standard library.
"""
import json
import re
import sys

RESERVED = "sip:anonymous@anonymous.invalid"


class SyntaxErr(Exception):
    pass


class UnauthErr(Exception):
    pass


class IdentErr(Exception):
    pass


class UpstreamErr(Exception):
    pass


# ---------------------------------------------------------------------------
# character classes
# ---------------------------------------------------------------------------

TOKEN_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-.!%*_+`'~"
)
# permitted USER characters in a sip URI (letters/digits and - _ . ! ~ * ' ( ) +)
USER_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.!~*'()+"
)
HEX_CHARS = frozenset("0123456789abcdefABCDEF")
ALNUM_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
)
WS = " \t"

# anything outside printable ASCII / HTAB / CR / LF anywhere is syntax
BAD_CHAR_RE = re.compile(r"[^\t\n\r\x20-\x7e]")
# bare CR or bare LF inside the header section
BARE_END_RE = re.compile(r"\r(?!\n)|(?<!\r)\n")

CALLID_RE = re.compile(r"[A-Za-z0-9_.@+-]{1,128}")
CSEQ_RE = re.compile(r"([0-9]+)[ \t]+(INVITE|MESSAGE)")
CL_RE = re.compile(r"[0-9]+")
_TOK = r"[A-Za-z0-9\-.\!%*_+`'~]"
DISPLAY_RE = re.compile(_TOK + r"+(?:[ \t]+" + _TOK + r"+)*[ \t]*")

COMPACT = {
    "f": "from",
    "t": "to",
    "i": "call-id",
    "l": "content-length",
    "c": "content-type",
}
REQUIRED = ("from", "to", "call-id", "cseq", "content-length")
SINGLETONS = ("p-preferred-identity", "remote-party-id", "privacy", "content-type")


# ---------------------------------------------------------------------------
# URI grammar and lexical normalization
# ---------------------------------------------------------------------------

def _decode_user(raw):
    if not raw:
        raise SyntaxErr()
    out = []
    i = 0
    n = len(raw)
    while i < n:
        c = raw[i]
        if c == "%":
            if i + 2 >= n:
                raise SyntaxErr()
            h1, h2 = raw[i + 1], raw[i + 2]
            if h1 not in HEX_CHARS or h2 not in HEX_CHARS:
                raise SyntaxErr()
            ch = chr(int(h1 + h2, 16))
            if ch not in USER_CHARS:
                raise SyntaxErr()
            out.append(ch)
            i += 3
        else:
            if c not in USER_CHARS:
                raise SyntaxErr()
            out.append(c)
            i += 1
    return "".join(out)


def _norm_host(raw):
    h = raw
    if h.endswith("."):
        h = h[:-1]
    if not h:
        raise SyntaxErr()
    if len(h) > 253:
        raise SyntaxErr()
    for label in h.split("."):
        if not 1 <= len(label) <= 63:
            raise SyntaxErr()
        for ch in label:
            if ch == "-":
                continue
            if ch not in ALNUM_CHARS:
                raise SyntaxErr()
        if label[0] not in ALNUM_CHARS or label[-1] not in ALNUM_CHARS:
            raise SyntaxErr()
    return h.lower()

def _tel_rest(rest):
    if not rest.startswith("+"):
        raise SyntaxErr()
    digits = rest[1:]
    if not 1 <= len(digits) <= 15:
        raise SyntaxErr()
    for ch in digits:
        if ch not in "0123456789":
            raise SyntaxErr()
    if digits[0] == "0":
        raise SyntaxErr()
    return "+" + digits


def parse_uri(raw):
    """Parse a sip or tel URI and return its normalized string form."""
    colon = raw.find(":")
    if colon <= 0:
        raise SyntaxErr()
    scheme = raw[:colon].lower()
    rest = raw[colon + 1:]
    if scheme == "sip":
        at = rest.find("@")
        if at < 0:
            raise SyntaxErr()
        host_raw = rest[at + 1:]
        if "@" in host_raw:
            raise SyntaxErr()
        user = _decode_user(rest[:at])
        host = _norm_host(host_raw)
        return "sip:" + user + "@" + host
    if scheme == "tel":
        return "tel:" + _tel_rest(rest)
    raise SyntaxErr()


# ---------------------------------------------------------------------------
# address / display-name grammar
# ---------------------------------------------------------------------------

def _skip_ws(s, i):
    while i < len(s) and s[i] in WS:
        i += 1
    return i


def _skip_quoted(s, i):
    """s[i] is a double quote; return index just after the closing quote."""
    n = len(s)
    i += 1
    while i < n:
        c = s[i]
        if c == "\\":
            if i + 1 >= n:
                raise SyntaxErr()          # dangling escape
            nxt = s[i + 1]
            if not (0x20 <= ord(nxt) <= 0x7E or nxt == "\t"):
                raise SyntaxErr()
            i += 2
        elif c == '"':
            return i + 1
        else:
            if not (0x20 <= ord(c) <= 0x7E or c == "\t"):
                raise SyntaxErr()
            i += 1
    raise SyntaxErr()                      # unterminated quoted string


def parse_address(value):
    """Parse one address; return (normalized_uri, index_after_address)."""
    n = len(value)
    if not n:
        raise SyntaxErr()
    if value[0] == '"':
        i = _skip_quoted(value, 0)
        j = _skip_ws(value, i)
        if j >= n or value[j] != "<":
            raise SyntaxErr()
        i = j
    else:
        lt = value.find("<")
        if lt == -1:
            # bare URI: URI characters never include SP/HTAB/';'
            end = 0
            while end < n and value[end] not in "; \t":
                end += 1
            return parse_uri(value[:end]), end
        pre = value[:lt]
        if pre.strip(WS):
            if DISPLAY_RE.fullmatch(pre) is None:
                raise SyntaxErr()
        i = lt
    i += 1                                   # consume '<'
    j = _skip_ws(value, i)
    k = j
    while k < n and value[k] not in WS and value[k] != ">":
        k += 1
    if k == j:
        raise SyntaxErr()                    # empty address
    uri_raw = value[j:k]
    m = _skip_ws(value, k)
    if m >= n or value[m] != ">":
        raise SyntaxErr()                    # stray text / nested brackets
    return parse_uri(uri_raw), m + 1


def parse_addr_tag(value):
    """From / To: one address plus an optional ;tag=TOKEN."""
    norm, i = parse_address(value)
    n = len(value)
    tag = None
    j = _skip_ws(value, i)
    if j < n:
        if value[j] != ";":
            raise SyntaxErr()
        j += 1
        j = _skip_ws(value, j)
        if value[j:j + 3].lower() != "tag":
            raise SyntaxErr()
        j += 3
        j = _skip_ws(value, j)
        if j >= n or value[j] != "=":
            raise SyntaxErr()
        j += 1
        j = _skip_ws(value, j)
        start = j
        while j < n and value[j] in TOKEN_CHARS:
            j += 1
        tag = value[start:j]
        if not 1 <= len(tag) <= 128:
            raise SyntaxErr()
        j = _skip_ws(value, j)
        if j != n:
            raise SyntaxErr()
    return norm, tag


def parse_single_address(value):
    """PPI / RPID: exactly one address, no header parameters."""
    norm, i = parse_address(value)
    if i != len(value):
        raise SyntaxErr()
    return norm


def split_pai(value):
    """Split a PAI value on commas outside quotes and angle brackets."""
    parts = []
    start = 0
    i = 0
    n = len(value)
    while i < n:
        c = value[i]
        if c == '"':
            i = _skip_quoted(value, i)
        elif c == "<":
            gt = value.find(">", i)
            if gt == -1:
                raise SyntaxErr()
            i = gt + 1
        elif c == ",":
            parts.append(value[start:i])
            start = i + 1
            i += 1
        else:
            i += 1
    parts.append(value[start:])
    return parts


# ---------------------------------------------------------------------------
# request framing and header grammar
# ---------------------------------------------------------------------------

def _parse_request_line(line):
    parts = line.split(" ")
    if len(parts) != 3:
        raise SyntaxErr()
    method, uri_raw, version = parts
    if method not in ("INVITE", "MESSAGE"):
        raise SyntaxErr()
    if version != "SIP/2.0":
        raise SyntaxErr()
    norm = parse_uri(uri_raw)
    if not norm.startswith("sip:"):
        raise SyntaxErr()
    return method, norm


class Parsed(object):
    __slots__ = (
        "method", "req_uri", "body", "call_id", "cseq_num", "ctype",
        "privacy_id", "from_norm", "from_tag", "from_anon",
        "to_norm", "to_tag", "ppi_norm", "rpid_norm", "pai_norms",
    )


def parse_request(text):
    if len(text) > 32768:
        raise SyntaxErr()
    if BAD_CHAR_RE.search(text):
        raise SyntaxErr()
    idx = text.find("\r\n\r\n")
    if idx == -1:
        raise SyntaxErr()                    # missing terminator
    head = text[:idx]
    body = text[idx + 4:]
    if BARE_END_RE.search(head):
        raise SyntaxErr()

        raise SyntaxErr()
    lines = head.split("\r\n")
    method, req_uri = _parse_request_line(lines[0])

    # unfolding: continuation replaces line break + leading ws run with one SP
    logical = []
    for line in lines[1:]:
        if line[:1] in (" ", "\t"):
            if not logical:
                raise SyntaxErr()            # orphan continuation
            logical[-1] = logical[-1] + " " + line.lstrip(" \t")
        else:
            logical.append(line)

    fields = []
    for ln in logical:
        m = len(ln)
        j = 0
        while j < m and ln[j] in TOKEN_CHARS:
            j += 1
        if j == 0:
            raise SyntaxErr()
        name = ln[:j].lower()
        name = COMPACT.get(name, name)
        k = _skip_ws(ln, j)
        if k >= m or ln[k] != ":":
            raise SyntaxErr()
        fields.append((name, ln[k + 1:].strip(WS)))

    by = {}
    for name, value in fields:
        by.setdefault(name, []).append(value)
    for name in REQUIRED:
        if len(by.get(name, ())) != 1:
            raise SyntaxErr()
    for name in SINGLETONS:
        if len(by.get(name, ())) > 1:
            raise SyntaxErr()

    p = Parsed()
    p.method = method
    p.req_uri = req_uri
    p.body = body

    p.call_id = by["call-id"][0]
    if CALLID_RE.fullmatch(p.call_id) is None:
        raise SyntaxErr()

    mm = CSEQ_RE.fullmatch(by["cseq"][0])
    if mm is None:
        raise SyntaxErr()
    num = int(mm.group(1))
    if not 1 <= num <= 2147483647:
        raise SyntaxErr()
    if mm.group(2) != method:
        raise SyntaxErr()
    p.cseq_num = num

    cl = by["content-length"][0]
    if CL_RE.fullmatch(cl) is None:
        raise SyntaxErr()
    if int(cl) != len(body):
        raise SyntaxErr()

    p.ctype = None
    if "content-type" in by:
        p.ctype = by["content-type"][0]
        if not p.ctype:
            raise SyntaxErr()

    p.privacy_id = False
    if "privacy" in by:
        pv = by["privacy"][0].lower()
        if pv == "id":
            p.privacy_id = True
        elif pv != "none":
            raise SyntaxErr()

    p.from_norm, p.from_tag = parse_addr_tag(by["from"][0])
    p.to_norm, p.to_tag = parse_addr_tag(by["to"][0])
    p.from_anon = (p.from_norm == RESERVED)

    p.ppi_norm = None
    if "p-preferred-identity" in by:
        norm = parse_single_address(by["p-preferred-identity"][0])
        if norm == RESERVED:
            raise SyntaxErr()
        p.ppi_norm = norm

    p.rpid_norm = None
    if "remote-party-id" in by:
        norm = parse_single_address(by["remote-party-id"][0])
        if norm == RESERVED:
            raise SyntaxErr()
        p.rpid_norm = norm

    pai_norms = []
    for value in by.get("p-asserted-identity", ()):
        for part in split_pai(value):
            part = part.strip(WS)
            norm = parse_single_address(part)
            if norm == RESERVED:
                raise SyntaxErr()
            pai_norms.append(norm)
    if len(pai_norms) > 2:
        raise SyntaxErr()
    if len(pai_norms) == 2:
        kinds = {pai_norms[0].split(":", 1)[0], pai_norms[1].split(":", 1)[0]}
        if kinds != {"sip", "tel"}:
            raise SyntaxErr()
    p.pai_norms = pai_norms
    return p


# ---------------------------------------------------------------------------
# boundary policy
# ---------------------------------------------------------------------------

def _domain(ident):
    if "@" not in ident:
        raise IdentErr()
    return ident.rsplit("@", 1)[1]


def _resolve_local(claim, allowed, local_domains, alias):
    ident = alias.get(claim)
    if ident is None:
        raise IdentErr()
    if ident not in allowed:
        raise IdentErr()
    if _domain(ident) not in local_domains:
        raise IdentErr()
    return ident


def select_identity(p, ingress, gw_tables, alias, accounts):
    kind = ingress.get("kind")
    local_domains, peers = gw_tables
    if kind == "local":
        acct = accounts.get(ingress.get("subject"))
        if acct is None:
            raise UnauthErr()
        primary, allowed = acct
        # Every nonanonymous From and any PPI must resolve to an allowed
        # account identity whose canonical domain is hosted here.
        if not p.from_anon:
            _resolve_local(p.from_norm, allowed, local_domains, alias)
        if p.ppi_norm is not None:
            selected = _resolve_local(p.ppi_norm, allowed, local_domains, alias)
        elif not p.from_anon:
            selected = alias[p.from_norm]
        else:
            selected = primary
        # The selected identity must also be hosted and allowed.
        if selected not in allowed:
            raise IdentErr()
        if _domain(selected) not in local_domains:
            raise IdentErr()
        return "local", selected
    if kind == "peer":
        auth = peers.get(ingress.get("name"))
        if auth is None:
            raise UnauthErr()
        if not p.pai_norms:
            raise UnauthErr()
        ident = None
        for claim in p.pai_norms:
            got = alias.get(claim)
            if got is None:
                raise IdentErr()
            if ident is None:
                ident = got
            elif got != ident:
                raise IdentErr()
        if _domain(ident) not in auth:
            raise IdentErr()
        if not p.from_anon and alias.get(p.from_norm) != ident:
            raise IdentErr()
        if p.ppi_norm is not None and alias.get(p.ppi_norm) != ident:
            raise IdentErr()
        if p.rpid_norm is not None and alias.get(p.rpid_norm) != ident:
            raise IdentErr()
        return "peer", ident
    raise UnauthErr()


# ---------------------------------------------------------------------------
# wire serialization
# ---------------------------------------------------------------------------

